// Vector search only RANKS (nearest 3, best first). Distance cannot decide whether the base answers a question (see raw/n8n/2026-10-01-pgvector-knowledge-base-report.md), so the Gate node decides.
const question = String($('Trigger').first().json.question ?? '').trim();
const hits = $input.all().map(i => i.json).filter(x => x && x.document);
const passages = hits.map(x => `[${x.document.metadata.topic}] ${x.document.pageContent.replace(/^.*\n/, '')}`);
return [{ json: { question, passages: passages.join('\n\n'), count: passages.length } }];

// Fail OPEN: only a clear NO from the gate means NOT_FOUND. If the gate node failed (its item then has no text) or answered anything else, the answer is FOUND.
const c = $('Collect').first().json;
if (!c.count) return [{ json: { verdict: 'NOT_FOUND' } }];
const answer = String($input.first().json.text ?? $input.first().json.output ?? '').trim().toUpperCase();
if (/^NO\b/.test(answer)) return [{ json: { verdict: 'NOT_FOUND' } }];
return [{ json: { verdict: 'FOUND\n' + c.passages } }];
